   450  static gboolean
   451  fu_coswid_firmware_parse(FuFirmware *firmware,
   452                           GInputStream *stream,
   453                           gsize offset,
   454                           FwupdInstallFlags flags,
   455                           GError **error)
   456  {
   457  #ifdef HAVE_CBOR
   458          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(firmware);
   459          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   460          struct cbor_load_result result = {0x0};
   461          struct cbor_pair *pairs = NULL;
   462          g_autoptr(cbor_item_t) item = NULL;
   463          g_autoptr(GBytes) fw = NULL;
   464
   465          fw = fu_input_stream_read_bytes(stream, offset, G_MAXSIZE, error);
   466          if (fw == NULL)
   467                  return FALSE;
   468          item = cbor_load(g_bytes_get_data(fw, NULL), g_bytes_get_size(fw), &result);
   469          if (item == NULL) {
   470                  g_set_error(error,
   471                              FWUPD_ERROR,
   472                              FWUPD_ERROR_NOT_SUPPORTED,
   473                              "failed to parse CBOR at offset 0x%x: 0x%x",
   474                              (guint)result.error.position,
   475                              result.error.code);
   476                  return FALSE;
   477          }
   478          fu_firmware_set_size(firmware, result.read);
   479
   480          /* pretty-print the result */
   481          if (g_getenv("FWUPD_CBOR_VERBOSE") != NULL) {
   482                  cbor_describe(item, stdout);
   483                  fflush(stdout);
   484          }
   485
   486          /* sanity check */
   487          if (!cbor_isa_map(item)) {
   488                  g_set_error_literal(error,
   489                                      FWUPD_ERROR,
   490                                      FWUPD_ERROR_INVALID_DATA,
   491                                      "root item is not a map");
   492                  return FALSE;
   493          }
   494
   495          /* parse out anything interesting */
   496          pairs = cbor_map_handle(item);
   497          for (gsize i = 0; i < cbor_map_size(item); i++) {
   498                  FuCoswidTag tag_id = cbor_get_uint8(pairs[i].key);
   499
   500                  /* identity can be specified as a string or in binary */
   501                  if (tag_id == FU_COSWID_TAG_TAG_ID) {
   502                          g_autofree gchar *str = NULL;
   503                          if (cbor_isa_string(pairs[i].value)) {
   504                                  str = fu_coswid_firmware_strndup(pairs[i].value);
   505                          } else if (cbor_isa_bytestring(pairs[i].value) &&
   506                                     cbor_bytestring_length(pairs[i].value) == 16) {
   507                                  str = fwupd_guid_to_string(
   508                                      (const fwupd_guid_t *)cbor_bytestring_handle(pairs[i].value),
   509                                      FWUPD_GUID_FLAG_NONE);
   510                          }
   511                          if (str != NULL)
   512                                  fu_firmware_set_id(firmware, str);
   513                  } else if (tag_id == FU_COSWID_TAG_SOFTWARE_NAME) {
   514                          priv->product = fu_coswid_firmware_strndup(pairs[i].value);
   515                  } else if (tag_id == FU_COSWID_TAG_SOFTWARE_VERSION) {
   516                          g_autofree gchar *str = fu_coswid_firmware_strndup(pairs[i].value);
   517                          fu_firmware_set_version(firmware, str);
   518                  } else if (tag_id == FU_COSWID_TAG_VERSION_SCHEME) {
   519                          priv->version_scheme = cbor_get_uint16(pairs[i].value);
   520                  } else if (tag_id == FU_COSWID_TAG_SOFTWARE_META) {
   521                          if (!fu_coswid_firmware_parse_one_or_many(self,
   522                                                                    pairs[i].value,
   523                                                                    fu_coswid_firmware_parse_meta,
   524                                                                    NULL, /* user_data */
   525                                                                    error))
   526                                  return FALSE;
   527                  } else if (tag_id == FU_COSWID_TAG_LINK) {
   528                          if (!fu_coswid_firmware_parse_one_or_many(self,
   529                                                                    pairs[i].value,
   530                                                                    fu_coswid_firmware_parse_link,
   531                                                                    NULL, /* user_data */
   532                                                                    error))
   533                                  return FALSE;
   534                  } else if (tag_id == FU_COSWID_TAG_PAYLOAD) {
   535                          if (!fu_coswid_firmware_parse_one_or_many(self,
   536                                                                    pairs[i].value,
   537                                                                    fu_coswid_firmware_parse_payload,
   538                                                                    NULL, /* user_data */
   539                                                                    error))
   540                                  return FALSE;
   541                  } else if (tag_id == FU_COSWID_TAG_ENTITY) {
   542                          if (!fu_coswid_firmware_parse_one_or_many(self,
   543                                                                    pairs[i].value,
   544                                                                    fu_coswid_firmware_parse_entity,
   545                                                                    NULL, /* user_data */
   546                                                                    error))
   547                                  return FALSE;
   548                  } else {
   549                          g_debug("unhandled tag %s from root", fu_coswid_tag_to_string(tag_id));
   550                  }
   551          }
   552
   553          /* device not supported */
   554          if (fu_firmware_get_id(firmware) == NULL && fu_firmware_get_version(firmware) == NULL &&
   555              priv->product == NULL && priv->entities->len == 0 && priv->links->len == 0) {
   556                  g_set_error_literal(error,
   557                                      FWUPD_ERROR,
   558                                      FWUPD_ERROR_NOT_SUPPORTED,
   559                                      "not enough SBoM data");
   560                  return FALSE;
   561          }
   562
   563          /* success */
   564          return TRUE;
   565  #else
   566          g_set_error_literal(error,
   567                              FWUPD_ERROR,
   568                              FWUPD_ERROR_NOT_SUPPORTED,
   569                              "not compiled with CBOR support");
   570          return FALSE;
   571  #endif
   572  }
